package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity@Table(name="spms_rating_assessment",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_assessment_revision",columnNames={"agency_id","root_assessment_id","revision_no"}))
public class PerformanceRatingAssessment extends RspAuditedEntity {public enum Type{SELF,SUPERVISOR,CALIBRATED,APPEAL_MODIFIED}public enum Status{DRAFT,SUBMITTED,SUPERSEDED,VOIDED}@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="root_assessment_id",nullable=false,length=36)private String rootAssessmentId;@Column(name="revision_no",nullable=false)private int revisionNo;@Column(name="supersedes_id",length=36)private String supersedesId;@Enumerated(EnumType.STRING)@Column(name="assessment_type",nullable=false,length=20)private Type type;@Column(name="author_employee_no",nullable=false,length=100)private String authorEmployeeNo;@Column(length=4000)private String summary;@Column(name="raw_score",nullable=false,precision=19,scale=8)private BigDecimal rawScore;@Column(name="rounded_score",nullable=false,precision=19,scale=6)private BigDecimal roundedScore;@Column(name="rating_band_id",nullable=false,length=36)private String ratingBandId;@Column(name="rating_label",nullable=false,length=200)private String ratingLabel;@Column(name="formula_version",nullable=false,length=40)private String formulaVersion;@Column(name="calculation_fingerprint",nullable=false,length=64)private String calculationFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;protected PerformanceRatingAssessment(){}public PerformanceRatingAssessment(String a,String c,String root,int revision,String prior,Type type,String author,String summary,BigDecimal raw,BigDecimal rounded,String band,String label,String formula,String fp){super(a);ratingCaseId=requiredText(c,"ratingCaseId");rootAssessmentId=requiredText(root,"rootAssessmentId");if(revision<1)throw new IllegalArgumentException("revisionNo must be positive");revisionNo=revision;supersedesId=optionalText(prior);this.type=type;authorEmployeeNo=requiredText(author,"authorEmployeeNo");apply(summary,raw,rounded,band,label,formula,fp);status=Status.DRAFT;}public void edit(String summary,BigDecimal raw,BigDecimal rounded,String band,String label,String formula,String fp){if(status!=Status.DRAFT)throw new IllegalStateException("Only a draft assessment may be edited");apply(summary,raw,rounded,band,label,formula,fp);}private void apply(String summary,BigDecimal raw,BigDecimal rounded,String band,String label,String formula,String fp){this.summary=optionalText(summary);rawScore=raw;roundedScore=rounded;ratingBandId=requiredText(band,"ratingBandId");ratingLabel=requiredText(label,"ratingLabel");formulaVersion=requiredText(formula,"formulaVersion");calculationFingerprint=requiredText(fp,"calculationFingerprint");}public void submit(String actor,Instant at){if(status!=Status.DRAFT)throw new IllegalStateException("Only a draft assessment may be submitted");status=Status.SUBMITTED;submittedBy=requiredText(actor,"actor");submittedAt=at;}public void supersede(){if(status!=Status.SUBMITTED)throw new IllegalStateException("Only a submitted assessment may be corrected");status=Status.SUPERSEDED;}public String getRatingCaseId(){return ratingCaseId;}public String getRootAssessmentId(){return rootAssessmentId;}public int getRevisionNo(){return revisionNo;}public String getSupersedesId(){return supersedesId;}public Type getType(){return type;}public String getAuthorEmployeeNo(){return authorEmployeeNo;}public String getSummary(){return summary;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getRoundedScore(){return roundedScore;}public String getRatingBandId(){return ratingBandId;}public String getRatingLabel(){return ratingLabel;}public String getFormulaVersion(){return formulaVersion;}public String getCalculationFingerprint(){return calculationFingerprint;}public Status getStatus(){return status;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}}
